'use client';

import React, { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { useParams, useSearchParams, useRouter } from 'next/navigation';
import CheckoutForm from './checkout/CheckoutForm';
import OrderSummary from './checkout/OrderSummary';

export default function PropFirmCheckout() {

    const params = useParams();
    const searchParams = useSearchParams();
    const router = useRouter();
    const sessionId = params?.orderId as string;

    const [state, setState] = useState({
        amount: '',
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        address: '',
        city: '',
        zip: '',
        country: 'India',
        agreed: false,
        loading: false,
        error: ''
    });

    const [selectedPlan, setSelectedPlan] = useState('');
    const [orderId, setOrderId] = useState('');

    const PLANS = [
        { id: '5k', name: '5K Challenge', price: 2499, label: '$5,000 Account' },
        { id: '10k', name: '10K Challenge', price: 4499, label: '$10,000 Account' },
        { id: '20k', name: '20K Challenge', price: 8499, label: '$20,000 Account' },
        // { id: '50k', name: '50K Challenge', price: 4999, label: '$50,000 Account' }, // temporarily hidden
        { id: '100k', name: '100K Challenge', price: 29999, label: '$100,000 Account' },
    ];

    useEffect(() => {
        // console.log("Init checkout with:", sessionId);

        const qAmount = searchParams.get('amount');
        if (qAmount) {
            const plan = PLANS.find(p => p.price.toString() === qAmount);
            if (plan) setSelectedPlan(plan.id);
            setState(s => ({ ...s, amount: qAmount }));
        }

        if (sessionId) {
            fetchTransaction();
        }
    }, [sessionId]);

    const fetchTransaction = async () => {
        try {
            const { data } = await supabase
                .from('transactions')
                .select('*')
                .or(`id.eq.${sessionId},session_id.eq.${sessionId}`)
                .single();

            if (data) {
                const names = (data.customer_details?.name || '').split(' ');
                setState(prev => ({
                    ...prev,
                    amount: data.amount,
                    firstName: names[0] || '',
                    lastName: names.slice(1).join(' ') || '',
                    email: data.customer_details?.email || '',
                }));

                if (data.order_id) setOrderId(data.order_id);

                const match = PLANS.find(p => p.price.toString() == data.amount);
                if (match) setSelectedPlan(match.id);
            }
        } catch (e) {
            console.log("Error loading tx:", e);
        }
    };

    const handlePlanSelect = (id: string) => {
        const p = PLANS.find(x => x.id === id);
        if (p) {
            setSelectedPlan(id);
            setState(prev => ({ ...prev, amount: p.price.toString() }));
        }
    };

    const handleChange = (key: string, val: any) => {
        setState(prev => ({ ...prev, [key]: val, error: '' }));
    };

    const handleSubmit = async (e: any) => {
        setState(s => ({ ...s, loading: true }));

        try {
            // basic validation
            if (!state.email || !state.firstName || !state.phone) {
                throw new Error("Please fill in all required fields");
            }

            const payload = {
                session_id: sessionId,
                amount: state.amount,
                utr: `TEMP-${sessionId}`,
                status: 'pending_payment',
                customer_details: {
                    name: `${state.firstName} ${state.lastName}`,
                    email: state.email,
                    phone: state.phone,
                    address: state.address,
                    city: state.city,
                    country: state.country,
                }
            };

            // DB Upsert
            const { data: existing } = await supabase.from('transactions').select('id').eq('session_id', sessionId).single();

            if (existing) {
                await supabase.from('transactions').update(payload).eq('session_id', sessionId);
            } else {
                await supabase.from('transactions').insert([payload]);
            }

            // Redirect
            router.push(`/secure-checkout/${sessionId}?mode=payment`);

        } catch (err: any) {
            console.error(err);
            setState(s => ({ ...s, loading: false, error: err.message || 'Something went wrong' }));
        }
    };

    return (
        <div className="min-h-screen bg-[#F0F2F5] flex justify-center p-4">
            <div className="bg-white w-full max-w-5xl rounded-2xl shadow-xl flex flex-col md:flex-row overflow-hidden min-h-[600px]">

                <OrderSummary
                    amount={state.amount}
                    planName={PLANS.find(p => p.id === selectedPlan)?.name}
                    planLabel={PLANS.find(p => p.id === selectedPlan)?.label}
                    officialOrderId={orderId}
                />

                <div className="flex-1 p-6 md:p-10 overflow-y-auto">
                    <CheckoutForm
                        state={state}
                        plans={PLANS}
                        selectedPlan={selectedPlan}
                        submitConfig={handleSubmit}
                        onChange={handleChange}
                        onPlanSelect={handlePlanSelect}
                    />
                </div>

            </div>
        </div>
    );
}
